import { award } from "./points";
import { VERSES, verseOf, wordsOf, type Verse } from "./arabicQuran";

// UI languages of the course: German, English (base) and Arabic plus the other eleven site languages.
// A text without an entry in the visitor's language falls back to English (`tx`).
export type XLang = "tr" | "ur" | "fa" | "ps" | "fr" | "es" | "id" | "ms" | "bn" | "ru" | "zh";
export type Lang = "de" | "en" | "ar" | XLang;
const LANG_SET: Record<Lang, true> = { de: true, en: true, ar: true, tr: true, ur: true, fa: true, ps: true, fr: true, es: true, id: true, ms: true, bn: true, ru: true, zh: true };
export const LANGS = Object.keys(LANG_SET) as Lang[];
export type L2 = { de: string; en: string; ar?: string } & { [K in XLang]?: string };
export type Letter = { ch: string; name: string; tr: string; connects: boolean; sound: L2; similar?: string[] };

